3	static void
4	gyrokinetic_forward_euler(gkyl_gyrokinetic_app* app, double tcurr, double dt,
5	  const struct gkyl_array *fin[], struct gkyl_array *fout[], 
6	  struct gkyl_array **bflux_in[], struct gkyl_array **bflux_out[], 
7	  const struct gkyl_array *fin_neut[], struct gkyl_array *fout_neut[], 
8	  struct gkyl_array **bflux_in_neut[], struct gkyl_array **bflux_out_neut[], 
9	  struct gkyl_update_status *st)
10	{
11	
12	  struct timespec wst_fe = gkyl_wall_clock();
13	  // Take a forward Euler step with the suggested time-step dt. This may
14	  // not be the actual time-step taken. However, the function will never
15	  // take a time-step larger than dt even if it is allowed by
16	  // stability. The actual time-step and dt_suggested are returned in
17	  // the status object.
18	  app->stat.nfeuler += 1;
19	
20	  // Compute the time rate of change of the distributions, df/dt.
21	  gyrokinetic_rhs(app, tcurr, dt, fin, fout, bflux_out, fin_neut, fout_neut, bflux_out_neut, st);
22	
23	  struct timespec wst = gkyl_wall_clock();
24	  // Complete update of distribution functions.
25	  double dta = st->dt_actual;
26	  for (int i=0; i<app->num_species; ++i) {
27	    struct gk_species *gks = &app->species[i];
28	    gk_species_step_f(gks, fout[i], dta, fin[i]);
29	    gk_species_bflux_accumulate(app, &gks->bflux, bflux_out[i], 1.0, bflux_in[i]);
30	  }
31	  for (int i=0; i<app->num_neut_species; ++i) {
32	    struct gk_neut_species *gkns = &app->neut_species[i];
33	    gk_neut_species_step_f(gkns, fout_neut[i], dta, fin_neut[i]);
34	    gk_neut_species_bflux_accumulate(app, &gkns->bflux, bflux_out_neut[i], 1.0, bflux_in_neut[i]);
35	  }
36	  app->stat.fwd_euler_step_f_tm += gkyl_time_diff_now_sec(wst);
37	  app->stat.fwd_euler_tm += gkyl_time_diff_now_sec(wst_fe);
38	
39	}
