187	            fout_neut[i] = app->neut_species[i].f1;
188	          }
189	          gyrokinetic_calc_field_and_apply_bc(app, tcurr, fout, bflux_out, fout_neut);
190	
191	          state = RK_STAGE_3;
192	        }
193	        break;
194	
195	      case RK_STAGE_3:
196	        for (int i=0; i<app->num_species; ++i) {
197	          struct gk_species *gks = &app->species[i];
198	          fin[i] = gks->f1;
199	          fout[i] = gks->fnew;
200	          // Boundary fluxes.
201	          bflux_in[i] = gks->bflux.f1;
202	          bflux_out[i] = gks->bflux.fnew;
203	        }
204	        for (int i=0; i<app->num_neut_species; ++i) {
205	          struct gk_neut_species *gkns = &app->neut_species[i];
206	          fin_neut[i] = gkns->f1;
207	          fout_neut[i] = gkns->fnew;
208	          // Boundary fluxes.
209	          bflux_in_neut[i] = gkns->bflux.f1;
210	          bflux_out_neut[i] = gkns->bflux.fnew;
211	        }
212	
213	        gyrokinetic_forward_euler(app, tcurr+dt/2, dt, fin, fout, bflux_in, bflux_out,
214	          fin_neut, fout_neut, bflux_in_neut, bflux_out_neut, &st);
215	
216	        if (st.dt_actual < dt) {
217	          // Recalculate the field.
218	          for (int i=0; i<app->num_species; ++i) {
219	            struct gk_species *gks = &app->species[i];
220	            fin[i] = gks->f;
221	            bflux_in[i] = gks->bflux.f;
222	          }
223	          gyrokinetic_calc_field(app, tcurr, fin, bflux_in);
224	
225	          // Collect stats.
226	          double dt_rel_diff = (dt-st.dt_actual)/st.dt_actual;
227	          app->stat.stage_3_dt_diff[0] = fmin(app->stat.stage_3_dt_diff[0],
228	            dt_rel_diff);
229	          app->stat.stage_3_dt_diff[1] = fmax(app->stat.stage_3_dt_diff[1],
230	            dt_rel_diff);
231	          app->stat.nstage_3_fail += 1;
232	
233	          dt = st.dt_actual;
234	          state = RK_STAGE_1; // Restart from stage 1.
235	
236	          app->stat.nstage_2_fail += 1;
237	        }
238	        else {
239	          struct timespec wst = gkyl_wall_clock();
240	          for (int i=0; i<app->num_species; ++i) {
241	            struct gk_species *gks = &app->species[i];
242	            // Step f.
243	            gk_species_combine(gks, gks->f1, 1.0/3.0, gks->f, 2.0/3.0, gks->fnew, &gks->local_ext);
244	            gk_species_copy_range(gks, gks->f, gks->f1, &gks->local_ext);
245	            // Step boundary fluxes.
246	            gk_species_bflux_set(app, &gks->bflux, gks->bflux.f, 2.0/3.0, gks->bflux.fnew);
247	            gk_species_bflux_calc_voltime_integrated_mom(app, gks, &gks->bflux, tcurr);
248	          }
249	
250	          for (int i=0; i<app->num_neut_species; ++i) {
251	            struct gk_neut_species *gkns = &app->neut_species[i];
252	            gk_neut_species_combine(gkns, gkns->f1, 1.0/3.0, gkns->f, 2.0/3.0, gkns->fnew, &gkns->local_ext);
253	            gk_neut_species_copy_range(gkns, gkns->f, gkns->f1, &gkns->local_ext);
254	            // Step boundary fluxes.
255	            gk_neut_species_bflux_set(app, &gkns->bflux, gkns->bflux.f, 2.0/3.0, gkns->bflux.fnew);
256	            gk_neut_species_bflux_calc_voltime_integrated_mom(app, gkns, &gkns->bflux, tcurr);
257	          }
258	          app->stat.time_stepper_arithmetic_tm += gkyl_time_diff_now_sec(wst);
259	
260	          // Apply positivity shift if requested.
261	          for (int i=0; i<app->num_species; ++i) {
262	            struct gk_species *gks = &app->species[i];
263	            gk_species_positivity_apply(app, gks, &gks->positivity, gks->fnew, gks->f);
264	          }
265	          for (int i=0; i<app->num_neut_species; ++i) {
266	            struct gk_neut_species *gkns = &app->neut_species[i];
267	            gk_neut_species_positivity_apply(app, gkns, &gkns->positivity, gkns->fnew, gkns->f);
268	          }
269	
270	          for (int i=0; i<app->num_species; ++i) {
271	            struct gk_species *gks = &app->species[i];
272	            fout[i] = gks->f;
273	            bflux_out[i] = gks->bflux.f;
274	          }
275	          for (int i=0; i<app->num_neut_species; ++i) {
276	            fout_neut[i] = app->neut_species[i].f;
277	          }
278	
279	          // Enforce quasineutrality of the positivity shifts.
280	          gyrokinetic_post_positivity_quasineut(app, fout);
281	
282	          // Compute the fields and apply BCs
283	          gyrokinetic_calc_field_and_apply_bc(app, tcurr, fout, bflux_out, fout_neut);
284	
285	          for (int i=0; i<app->num_species; ++i) {
286	            struct gk_species *gks = &app->species[i];
287	            // Compute moment of f_new to compute moment of df/dt.
288	            // Need to do it after the fields are updated.
289	            gk_species_calc_int_mom_dt(app, gks, dt, gks->fdot_mom_new);
290	          }
291	
292	          // Scale species according to some criteria.
293	          for (int i=0; i<app->num_species; ++i) {
294	            struct gk_species *gks = &app->species[i];
295	            gk_species_scaling_apply(app, gks, &gks->sca, gks->f, bflux_out);
296	          }
297	          for (int i=0; i<app->num_neut_species; ++i) {
298	            struct gk_neut_species *gkns = &app->neut_species[i];
299	            gk_neut_species_scaling_apply(app, gkns, &gkns->sca, gkns->f, bflux_out);
300	          }
301	
302	          // Compute field energy divided by dt for energy balance diagnostics.
303	          gk_field_calc_energy_dt(app, app->field, dt, app->field->em_energy_red_new);
304	
305	          state = RK_COMPLETE;
306	        }
307	        break;
308	
309	      case RK_COMPLETE: // can't happen: suppresses warning
310	        break;
311	    }
312	  }
