30	  up->phase_grid = *phase_grid;
31	  int cdim = conf_basis->ndim;
32	  int pdim = phase_basis->ndim;
33	  int vdim = pdim - cdim;
34	  int poly_order = phase_basis->poly_order;
35	  up->cdim = cdim;
36	  up->pdim = pdim;
37	
38	  up->charge = charge;
39	  up->mass = mass;
40	
41	  up->gk_geom = gkyl_gk_geometry_acquire(gk_geom);
42	  up->dg_geom = gkyl_dg_geom_acquire(dg_geom);
43	  up->gk_dg_geom = gkyl_gk_dg_geom_acquire(gk_dg_geom);
44	  up->vel_map = gkyl_velocity_map_acquire(vel_map);
45	
46	  if (type == GKYL_GK_COLLISIONLESS_ES) {
47	    for (int d=0; d<cdim; ++d) {
48	      // BC option in ->flux_surf kernel doesn't matter as long as it's not SKIP.
49	      up->flux_surf[d] = choose_gk_collisionless_flux_surf_conf_kern(d, cdim, vdim, poly_order, GKYL_BC_GK_SPECIES_ABSORB);
50	      up->flux_surf_edge_lo[d] = choose_gk_collisionless_flux_boundary_conf_kern(d, cdim, vdim,
51	        poly_order, bctype_conf[d], GKYL_LOWER_EDGE);
52	      up->flux_surf_edge_up[d] = choose_gk_collisionless_flux_boundary_conf_kern(d, cdim, vdim,
53	        poly_order, bctype_conf[GKYL_MAX_CDIM+d], GKYL_UPPER_EDGE);
54	    }
55	    up->flux_surfvpar[0] = choose_gk_collisionless_flux_surf_vpar_kern(cdim, vdim, poly_order);
56	  }
57	  else if (type == GKYL_GK_COLLISIONLESS_ES_NO_BY) {
58	    for (int d=0; d<cdim; ++d) {
59	      // BC option in ->flux_surf kernel doesn't matter as long as it's not SKIP.
60	      up->flux_surf[d] = choose_gk_collisionless_flux_no_by_surf_conf_kern(d, cdim, vdim, poly_order, GKYL_BC_GK_SPECIES_ABSORB);
61	      up->flux_surf_edge_lo[d] = choose_gk_collisionless_flux_boundary_conf_kern_no_by(d, cdim, vdim,
62	        poly_order, bctype_conf[d], GKYL_LOWER_EDGE);                                 
63	      up->flux_surf_edge_up[d] = choose_gk_collisionless_flux_boundary_conf_kern_no_by(d, cdim, vdim,
64	        poly_order, bctype_conf[GKYL_MAX_CDIM+d], GKYL_UPPER_EDGE);
65	    }
66	    up->flux_surfvpar[0] = choose_gk_collisionless_flux_no_by_surf_vpar_kern(cdim, vdim, poly_order);
67	  }
68	
69	  up->flags = 0;
70	  GKYL_CLEAR_CU_ALLOC(up->flags);
71	  up->on_dev = up; // self-reference on host
72	  
73	  return up;
74	}
