76	void gkyl_gk_collisionless_flux_surf(struct gkyl_gk_collisionless_flux *up, 
77	  const struct gkyl_range *conf_range, const struct gkyl_range *phase_range,
78	  const struct gkyl_range *conf_ext_range, const struct gkyl_range *phase_ext_range, const struct gkyl_array *phi, 
79	  const struct gkyl_array *fin, struct gkyl_array *yfield, struct gkyl_array* flux_surf, struct gkyl_array *cflrate)
80	{
81	#ifdef GKYL_HAVE_CUDA
82	  if (gkyl_array_is_cu_dev(flux_surf)) {
83	    return gkyl_gk_collisionless_flux_surf_cu(up, conf_range, phase_range,
84	      conf_ext_range, phase_ext_range, phi, fin, flux_surf, cflrate);
85	  }
86	#endif
87	  int pdim = up->pdim;
88	  int cdim = up->cdim;
89	  int idx[GKYL_MAX_DIM], idx_edge[GKYL_MAX_DIM], idx_vel[2];
90	  int idxL[GKYL_MAX_DIM];
91	  int idx_velL[2];
92	  double xc[GKYL_MAX_DIM];
93	
94	  struct gkyl_range vpar_range;
95	  int extend_lo[GKYL_MAX_DIM] = {0};
96	  int extend_up[GKYL_MAX_DIM] = {0};
97	  extend_lo[cdim] = -1;
98	  gkyl_range_extend(&vpar_range, phase_range, extend_lo, extend_up);
99	
100	  gkyl_array_clear(yfield, 0.0);
101	
102	  struct gkyl_range_iter iter;
103	  gkyl_range_iter_init(&iter, phase_range);
104	  while (gkyl_range_iter_next(&iter)) {
105	    gkyl_copy_int_arr(pdim, iter.idx, idx);
106	
107	    for (int d=cdim; d<pdim; d++) idx_vel[d-cdim] = iter.idx[d];
108	
109	    long loc_conf = gkyl_range_idx(conf_range, idx);
110	    long loc_vel = gkyl_range_idx(&up->vel_map->local_vel, idx_vel);
111	    long loc_phase = gkyl_range_idx(phase_range, idx);
112	
113	    gkyl_rect_grid_cell_center(&up->phase_grid, idx, xc);
114	
115	    const double *bmag_d = gkyl_array_cfetch(up->gk_geom->geo_corn.bmag, loc_conf);
116	    const double *vmap_d = gkyl_array_cfetch(up->vel_map->vmap, loc_vel);
117	    const double *vmapSq_d = gkyl_array_cfetch(up->vel_map->vmap_sq, loc_vel);
118	
119	    double *flux_surf_d = gkyl_array_fetch(flux_surf, loc_phase);
120	    double *cflrate_d = gkyl_array_fetch(cflrate, loc_phase);
121	
122	    for (int dir = 0; dir<cdim; ++dir) {
123	      gkyl_copy_int_arr(pdim, idx, idxL);
124	      idxL[dir] = idx[dir] - 1;
125	      long loc_confL = gkyl_range_idx(conf_range, idxL);
126	      long locL = gkyl_range_idx(phase_range, idxL);
127	      const double *fL = gkyl_array_cfetch(fin, locL);
128	      const double *fR = gkyl_array_cfetch(fin, loc_phase);
129	
130	      const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx);
131	      const struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx);
132	
133	      const double *jacgeo_rat_surfL_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_confL);
134	      const double *jacgeo_rat_surfR_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf);
135	
136	      const double *phiL_d = gkyl_array_cfetch(phi, loc_confL);
137	      const double *phiR_d = gkyl_array_cfetch(phi, loc_conf);
138	
139	      double *yfieldL = gkyl_array_fetch(yfield, locL);
140	      double *yfieldR = gkyl_array_fetch(yfield, loc_phase);
141	
142	      if (idx[dir] == phase_range->lower[dir]) {
143	        // Special case: this cell's own lower face is the domain/block
144	        // lower boundary. Use the dedicated lower-boundary kernel (chosen
145	        // from periodic/nonperiodic/multib variants based on the BC type),
146	        // as opposed to the plain interior kernel used below.
147	        cflrate_d[0] += up->flux_surf_edge_lo[dir](xc, up->phase_grid.dx, vmap_d, vmapSq_d, up->charge, up->mass,
148	          dgs, gkdgs, bmag_d, jacgeo_rat_surfL_d, jacgeo_rat_surfR_d, phiL_d, phiR_d, fL, fR, yfieldL, yfieldR, flux_surf_d);
149	      }
150	      else if (idx[dir] == phase_range->upper[dir]) {
151	        // Special case: if the phase space index is at the local configuration
152	        // space upper value, this (last interior) cell also owns an *extra*
153	        // face beyond itself: the domain/block upper boundary face, into the
154	        // ghost/ext range. We also need to evaluate alpha = +1 there to avoid
155	        // evaluating the geometry information in the ghost cells where it is
156	        // not defined when computing the final surface alpha we need (since
157	        // the surface alpha array stores only the *lower* surface expansion).
158	        // Use the dedicated upper-boundary kernel, symmetric with the lower
159	        // boundary case above.
160	        gkyl_copy_int_arr(pdim, idx, idx_edge);
161	        idx_edge[dir] = idx_edge[dir]+1;
162	        long loc_conf_ext = gkyl_range_idx(conf_ext_range, idx_edge);
163	        long loc_phase_ext = gkyl_range_idx(phase_ext_range, idx_edge);
164	
165	        double *cflrate_ext_d = gkyl_array_fetch(cflrate, loc_phase);
166	
167	        const double *fL = gkyl_array_cfetch(fin, loc_phase);
168	        const double *fR = gkyl_array_cfetch(fin, loc_phase_ext);
169	
170	        const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx_edge);
171	        const struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx_edge);
172	
173	        const double *jacgeo_rat_surfL_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf);
174	        const double *jacgeo_rat_surfR_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf_ext);
175	
176	        const double *phiL_d = gkyl_array_cfetch(phi, loc_conf);
177	        const double *phiR_d = gkyl_array_cfetch(phi, loc_conf_ext);
178	
179	        double *yfieldL = gkyl_array_fetch(yfield, loc_phase);
180	        double *yfieldR = gkyl_array_fetch(yfield, loc_phase_ext);
181	
182	        double* flux_surf_ext_d = gkyl_array_fetch(flux_surf, loc_phase_ext);
183	
184	        cflrate_ext_d[0] = GKYL_MAX2(cflrate_ext_d[0], up->flux_surf_edge_up[dir](xc, up->phase_grid.dx, vmap_d, vmapSq_d, up->charge, up->mass,
185	          dgs, gkdgs, bmag_d, jacgeo_rat_surfL_d, jacgeo_rat_surfR_d, phiL_d, phiR_d, fL, fR, yfieldL, yfieldR, flux_surf_ext_d));
186	      }  
187	      else {
188	        // Interior, lower cell surface.
189	        cflrate_d[0] += up->flux_surf[dir](xc, up->phase_grid.dx, vmap_d, vmapSq_d, up->charge, up->mass,
190	          dgs, gkdgs, bmag_d, jacgeo_rat_surfL_d, jacgeo_rat_surfR_d, phiL_d, phiR_d, fL, fR, yfieldL, yfieldR, flux_surf_d);
191	      }
192	
193	    }
194	  }
195	
196	  gkyl_range_iter_init(&iter, &vpar_range);
197	  while (gkyl_range_iter_next(&iter)) {
198	    gkyl_copy_int_arr(pdim, iter.idx, idx);
199	
200	    for (int d=cdim; d<pdim; d++) idx_vel[d-cdim] = iter.idx[d];
201	
202	    long loc_conf = gkyl_range_idx(conf_range, idx);
203	    long loc_vel = gkyl_range_idx(&up->vel_map->local_vel, idx_vel);
204	    long loc_phase = gkyl_range_idx(phase_range, idx);
205	
206	    gkyl_rect_grid_cell_center(&up->phase_grid, idx, xc);
207	
208	    const double *bmag_d = gkyl_array_cfetch(up->gk_geom->geo_corn.bmag, loc_conf);
209	    const double *vmap_d = gkyl_array_cfetch(up->vel_map->vmap, loc_vel);
210	    const double *vmapSq_d = gkyl_array_cfetch(up->vel_map->vmap_sq, loc_vel);
211	    const double *yfield_d = gkyl_array_cfetch(yfield, loc_phase);
212	
213	    double *flux_surf_d = gkyl_array_fetch(flux_surf, loc_phase);
214	    double *cflrate_d = gkyl_array_fetch(cflrate, loc_phase);
215	
216	    int dir=cdim;
217	    gkyl_copy_int_arr(pdim, idx, idxL);
218	    idxL[dir] = idx[dir] - 1;
219	    gkyl_copy_int_arr(pdim-cdim, idx_vel, idx_velL);
220	    idx_velL[0] = idx_velL[0]-1;
221	    long locL = gkyl_range_idx(phase_range, idxL);
222	    long loc_velL = gkyl_range_idx(&up->vel_map->local_vel, idx_velL);
223	    const double *fL = gkyl_array_cfetch(fin, locL);
224	    const double *fR = gkyl_array_cfetch(fin, loc_phase);
225	
226	    const double *vpL = gkyl_array_cfetch(up->vel_map->vmap_prime, loc_velL);
227	    const double *vpR = gkyl_array_cfetch(up->vel_map->vmap_prime, loc_vel);
228	
229	    const struct gkyl_dg_vol_geom *dgv = gkyl_dg_geom_get_vol(up->dg_geom, idx);
230	    const struct gkyl_gk_dg_vol_geom *gkdgv = gkyl_gk_dg_geom_get_vol(up->gk_dg_geom, idx);
231	    cflrate_d[0] += up->flux_surfvpar[0](xc, up->phase_grid.dx, vpL, vpR, vmap_d, vmapSq_d, up->charge, up->mass,
232	      dgv, gkdgv, bmag_d, yfield_d, fL, fR, flux_surf_d);
233	  }
